/**
 * @file task_switcher.h
 * @brief Task Switching System for GUIKit
 * 
 * Implements single-level task switching with RAM freeze/thaw:
 * - Freeze current task (A) to SD card
 * - Load and run new task (B) in RAM
 * - When B finishes, free B and restore A from SD card
 * 
 * Tasks A and B are responsible for their own standard methods.
 * Communication between tasks is via SD card files.
 * 
 * Example: JPEG to RGB conversion
 *   Task A (GUI) -> freeze -> Task B (converter) -> back -> Task A restored
 * 
 * Generated by Mistral Vibe
 * Date: 2026-08-16
 */

#ifndef TASK_SWITCHER_H
#define TASK_SWITCHER_H

#include <stdint.h>
#include <stdbool.h>

// ============================================================================
// TASK SWITCHER TYPES
// ============================================================================

/// @brief Task switcher states
typedef enum {
    TASK_STATE_NORMAL = 0,      ///< Running normally, no frozen parent
    TASK_STATE_FROZEN,         ///< Current task is frozen (parent task exists)
    TASK_STATE_ERROR           ///< Error occurred during switch
} TaskSwitcherState;

/// @brief Task switcher error codes
typedef enum {
    TASK_ERROR_NONE = 0,
    TASK_ERROR_NO_SDCARD,       ///< SD card not available
    TASK_ERROR_FREEZE_FAILED,   ///< Failed to freeze current task
    TASK_ERROR_LOAD_FAILED,     ///< Failed to load new task
    TASK_ERROR_RESTORE_FAILED,  ///< Failed to restore parent task
    TASK_ERROR_NO_FROZEN_TASK,  ///< No frozen task to restore
    TASK_ERROR_INSUFFICIENT_RAM ///< Not enough RAM for new task
} TaskSwitcherError;

/// @brief Task information structure
typedef struct {
    char kernel_path[64];      ///< Path to task kernel
    uint32_t ram_size;          ///< RAM size used by task
    uint32_t freeze_address;    ///< Address where task was frozen from
    uint32_t freeze_size;       ///< Size of frozen RAM
    char freeze_file[64];      ///< SD card file for frozen state
    bool valid;                ///< Is this task info valid
} TaskInfo;

/// @brief Task switcher configuration
typedef struct {
    char frozen_task_file[64];  ///< SD card path for frozen state (default: /tmp/frozen_task.bin)
    uint32_t min_free_ram;       ///< Minimum free RAM required to switch (default: 80%)
    bool auto_cleanup;          ///< Clean up frozen file after restore (default: true)
    bool debug;                ///< Enable debug output (default: false)
} TaskSwitcherConfig;

// ============================================================================
// DEFAULT CONFIGURATION
// ============================================================================

#define TASK_SWITCHER_DEFAULT_CONFIG \
    { \
        .frozen_task_file = "/tmp/frozen_task.bin", \
        .min_free_ram = 80,  // 80% free RAM required \
        .auto_cleanup = true, \
        .debug = false \
    }

// ============================================================================
// GLOBAL STATE
// ============================================================================

/// @brief Initialize task switcher with default config
void task_switcher_init(void);

/// @brief Initialize task switcher with custom config
/// @param config Pointer to configuration
void task_switcher_init_with_config(const TaskSwitcherConfig* config);

/// @brief Get current task switcher state
/// @return Current state
TaskSwitcherState task_switcher_get_state(void);

/// @brief Get last error code
/// @return Error code
TaskSwitcherError task_switcher_get_error(void);

/// @brief Get error message string
/// @param error Error code
/// @return Human-readable error message
const char* task_switcher_error_to_string(TaskSwitcherError error);

// ============================================================================
// CORE FUNCTIONS
// ============================================================================

/**
 * @brief Switch from current task to a new task
 * 
 * This function:
 * 1. Freezes current task RAM to SD card
 * 2. Loads new task kernel
 * 3. Jumps to new task
 * 
 * @param new_kernel_path Path to new task kernel (e.g., "/kernel/jpeg_converter.bin")
 * @return true on success, false on error (check task_switcher_get_error())
 * 
 * @note Does not return if successful - new task starts running
 * @note Requires SD card to be available
 * @note Requires at least min_free_ram percentage of RAM to be free
 */
bool task_switch_to(const char* new_kernel_path);

/**
 * @brief Restore parent task from frozen state
 * 
 * This function:
 * 1. Frees current task (Task B)
 * 2. Restores parent task (Task A) from SD card
 * 3. Resumes parent task execution
 * 
 * @return true on success, false on error (check task_switcher_get_error())
 * 
 * @note Does not return if successful - parent task resumes
 * @note If auto_cleanup is true, frozen file is deleted after restore
 */
bool task_restore(void);

/**
 * @brief Check if there is a frozen parent task
 * 
 * @return true if a parent task is frozen and can be restored
 */
bool task_has_frozen_parent(void);

/**
 * @brief Get information about the frozen parent task
 * 
 * @param info Pointer to TaskInfo struct to fill
 * @return true if parent task exists, false otherwise
 */
bool task_get_frozen_parent(TaskInfo* info);

/**
 * @brief Get information about the current task
 * 
 * @param info Pointer to TaskInfo struct to fill
 */
void task_get_current(TaskInfo* info);

// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================

/**
 * @brief Check if we have enough free RAM to switch
 * 
 * @param required_percent Minimum free RAM percentage required
 * @return true if enough RAM is available
 */
bool task_switcher_has_enough_ram(uint8_t required_percent);

/**
 * @brief Get current free RAM percentage
 * 
 * @return Free RAM percentage (0-100)
 */
uint8_t task_switcher_get_free_ram_percent(void);

/**
 * @brief Force cleanup of frozen task file
 * 
 * @return true on success
 */
bool task_switcher_cleanup_frozen(void);

// ============================================================================
// TASK COMMUNICATION HELPERS
// ============================================================================

/// @brief Standard path for task communication files
#define TASK_COMM_DIR "/tmp/task_comm/"

/**
 * @brief Save data for parent task to read after restore
 * 
 * @param filename Filename relative to TASK_COMM_DIR
 * @param data Pointer to data
 * @param size Size of data in bytes
 * @return true on success
 */
bool task_save_for_parent(const char* filename, const void* data, uint32_t size);

/**
 * @brief Load data saved by child task after restore
 * 
 * @param filename Filename relative to TASK_COMM_DIR
 * @param buffer Buffer to load into
 * @param buffer_size Size of buffer
 * @return Number of bytes loaded, or 0 on error
 */
uint32_t task_load_from_child(const char* filename, void* buffer, uint32_t buffer_size);

/**
 * @brief Check if child task saved a file
 * 
 * @param filename Filename to check
 * @return true if file exists
 */
bool task_child_has_file(const char* filename);

#endif // TASK_SWITCHER_H
